"""Password-only narrow-screen page. Session and receipts live only in memory."""
PAGE=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sisyfus 手机工作台</title>
<style nonce="NONCE">
:root{font:16px/1.6 system-ui,sans-serif;color:#332e28;background:#faf9f6}*{box-sizing:border-box}body{margin:0}main{max-width:760px;margin:auto;padding:20px 16px 64px;overflow-wrap:anywhere}header{display:flex;align-items:center;justify-content:space-between;gap:8px}h1{font-size:24px}h2{font-size:19px;margin-top:0}section{padding:22px 0;border-top:1px solid #e1ddd6}button,input,textarea,select{font:inherit;border:1px solid #d7cfc3;border-radius:8px;max-width:100%;padding:10px;background:white;color:inherit}button{min-height:44px;cursor:pointer}button.primary{background:#765e49;color:white}button:disabled{opacity:.5;cursor:default}textarea,input[type=password]{display:block;width:100%;margin:10px 0}textarea{resize:vertical;min-height:100px}label{display:block;margin:12px 0}small,.muted{color:#766e63}.notice{white-space:pre-wrap;overflow-wrap:anywhere}article{margin:12px 0;padding:12px;background:#f0ece5;border-radius:8px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}select{width:100%}details{margin-top:10px}iframe{width:100%;height:60vh;border:1px solid #ddd}#status{padding:12px 0;color:#80563b}input[type=checkbox]{width:20px;height:20px;vertical-align:middle}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #cda984;outline-offset:2px}[hidden]{display:none!important}@media(max-width:400px){main{padding:12px}h1{font-size:22px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><main><header><h1>Sisyfus 工作台</h1><button id="logout" hidden>退出</button></header><p class="muted">固定任务 · 先规划，再确认执行。普通聊天与阅读不会派发实现者。</p><p id="status" role="status" aria-live="polite">请输入访问密码。刷新后需重新登录。</p><p id="revoke" class="notice" role="status"></p>
<form id="login"><label for="password">访问密码</label><input id="password" type="password" autocomplete="current-password" required><button class="primary">登录</button></form>
<div id="private" hidden>
<section><h2>1 · 聊天与方案</h2><p id="binding" class="notice"></p><button id="create" class="primary">创建这项固定任务的对话</button><div id="messages"></div><form id="chat-form"><label for="chat-text">与 Lead 讨论</label><textarea id="chat-text" maxlength="4000" required></textarea><button data-mutate>发送消息</button></form><div id="proposal"></div></section>
<section><h2>2 · 审阅固定验收</h2><p id="readiness"></p><p id="approval" class="notice"></p><div id="checks"></div><label><input id="planning" type="checkbox">允许 Lead 规划（尚未允许实现调用）</label><button id="prepare" class="primary" data-mutate>确认并准备任务</button><p id="preparation" class="notice"></p></section>
<section><h2>3 · 机器安排</h2><p class="muted">本机默认保留。远端节点由本机控制器登记，手机仅选择明确允许的机器。</p><div id="placements"></div></section>
<section><h2>4 · 单独确认执行</h2><label><input id="execution" type="checkbox">允许 worker 执行已审阅的固定任务</label><button id="start" class="primary" data-mutate>Start 开始执行</button><p class="muted">暂停、恢复、Stop 本轮留在本机控制器。</p></section>
<section><h2>5 · 任务进度与工程结果</h2><button id="refresh">只读刷新 / 核对回执</button><p id="capture-meta" class="notice"></p><div id="graph"></div><div id="result"></div><form id="inbox-form"><label for="inbox-text">/btw 查询或补充资料</label><textarea id="inbox-text" maxlength="4000" required></textarea><button data-mutate>提交资料（不是开工许可）</button></form><div id="inbox"></div><p id="receipt" class="notice"></p><details><summary>固定报告版本（非最新动态图）</summary><p id="report-version" class="notice"></p><button id="report-open">打开这个固定版本</button><iframe id="report" sandbox hidden title="固定报告"></iframe></details></section></div>
<script nonce="NONCE">
'use strict';const $=id=>document.getElementById(id);let credential='',epoch=0,timer=null,polling=false,busy=false,unknown=false,chat=null,capture=null,reportURL=null;const requests=new Set();let revoking=0;
function element(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);return n;}
function show(id,value){$(id).textContent=typeof value==='string'?value:JSON.stringify(value,null,2);}
function clearPrivate(){epoch++;credential='';clearTimeout(timer);timer=null;for(const r of requests)r.abort();requests.clear();polling=false;busy=false;unknown=false;chat=null;capture=null;if(reportURL)URL.revokeObjectURL(reportURL);reportURL=null;$('report').removeAttribute('src');$('report').hidden=true;for(const id of ['binding','messages','proposal','readiness','approval','checks','preparation','placements','capture-meta','graph','result','inbox','receipt','report-version'])$(id).replaceChildren();$('chat-text').value='';$('inbox-text').value='';$('password').value='';$('planning').checked=false;$('execution').checked=false;$('private').hidden=true;$('login').hidden=false;$('logout').hidden=true;}
class RequestError extends Error{constructor(code,status=0){super(code);this.status=status;}}
async function api(path,body,bearer=credential,method){const c=new AbortController();requests.add(c);const timeout=setTimeout(()=>c.abort(),14000);try{const r=await fetch(path,{method:method||(body===undefined?'GET':'POST'),headers:{...(bearer?{Authorization:'Bearer '+bearer}:{}),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:c.signal,credentials:'omit',cache:'no-store',redirect:'error'});const value=await r.json();if(!r.ok){if([401,403,410].includes(r.status)&&bearer){clearPrivate();show('status','会话或权限已失效；请重新登录。')}throw new RequestError(value?.error?.code||'HTTP_REJECTED',r.status);}return value;}catch(e){if(e instanceof RequestError)throw e;throw new RequestError('CONNECTION_UNCERTAIN');}finally{clearTimeout(timeout);requests.delete(c);}}
function buttons(){const block=busy||unknown||!chat;document.querySelectorAll('[data-mutate]').forEach(b=>b.disabled=block);$('create').disabled=busy||unknown;$('prepare').disabled=block||!chat?.readiness?.ready||!!chat?.mission_id;$('start').disabled=block||chat?.placement_preparation?.status!=='ACK'||!!chat?.placement_start;}
function renderChat(value){chat=value;$('messages').replaceChildren();for(const m of value.messages||[]){const a=element('article');a.append(element('small',m.role==='user'?'你':'Lead'),element('p',m.text||''));$('messages').append(a);}$('proposal').replaceChildren();if(value.proposal){$('proposal').append(element('h3','方案'),element('p',value.proposal.objective||''),element('p',value.proposal.architecture||''));for(const d of value.proposal.deliverables||[])$('proposal').append(element('p','交付 · '+d));for(const t of value.proposal.tasks||[])$('proposal').append(element('article',(t.title||'')+' · '+(t.acceptance||'')));}show('readiness',value.readiness?.reason||value.status);show('approval','审批哈希：'+(value.approval_hash||'尚未产生'));$('checks').replaceChildren();for(const c of value.checks||[]){const d=element('details');d.append(element('summary','验收 · '+c.id),element('pre',JSON.stringify({pass_if:c.pass_if,fail_if:c.fail_if},null,2)));$('checks').append(d);}show('preparation',value.placement_preparation||'尚未准备');buttons();}
function renderGraph(s){const root=$('graph');root.replaceChildren(element('p',s.objective||'任务状态'),element('p','阶段：'+(s.phase||'未记录')+' · 全部核验：'+(s.all_verified===true?'是':'尚未确认')));const nodes=Array.isArray(s.nodes)?s.nodes:[];const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 340 '+Math.max(72,nodes.length*90));svg.setAttribute('width','100%');svg.setAttribute('role','img');svg.setAttribute('aria-label','同次捕获的任务依赖图');const draw=(tag,attrs,text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;svg.append(n);};nodes.forEach((n,i)=>{for(const dep of n.depends_on||[]){const j=nodes.findIndex(v=>v.id===dep);if(j>=0)draw('path',{d:'M 24 '+(j*90+48)+' L 10 '+(j*90+48)+' L 10 '+(i*90+24)+' L 24 '+(i*90+24),fill:'none',stroke:'#a78b70','stroke-width':2});}draw('rect',{x:24,y:i*90+8,width:306,height:64,rx:8,fill:'#ece6dc'});draw('text',{x:36,y:i*90+34,fill:'#332e28','font-size':14},String(n.id||'任务').slice(0,32));draw('text',{x:36,y:i*90+56,fill:'#765e49','font-size':13},(n.state||'')+' · '+(n.verdict||'UNVERIFIED'));});root.append(svg);for(const n of nodes){const a=element('article');a.append(element('strong',n.id||'任务'),element('p',n.objective||''),element('small','依赖：'+(n.depends_on||[]).join('、')+' · 尝试：'+(n.attempts||0)));root.append(a);}}
function renderResult(side){const root=$('result');root.replaceChildren(element('h3','工程结果'));if(side.status!=='OK'){root.append(element('p','结果投影：'+side.status+' · '+(side.error?.code||'未记录')));return;}const v=side.result;const paragraphs=v.conclusion?.statements||v.statements||v.reader_statements||[];if(v.answer)root.append(element('p',v.answer));for(const p of paragraphs)root.append(element('p',typeof p==='string'?p:p.text||p.statement||''));root.append(element('p','这是控制器证据投影；不是额外执行或验收许可。'));const d=element('details');d.append(element('summary','查看同次捕获的结构化证据'),element('pre',JSON.stringify(v,null,2)));root.append(d);}
function renderCapture(v){capture=v;show('capture-meta',v.captured_at+' · '+v.capture_hash);$('graph').replaceChildren();const s=v.capture.snapshot;renderGraph(s);const side=v.capture.engineering_result;renderResult(side);show('report-version',v.report?.available?'固定 SHA：'+v.report.sha256+'；独立于动态图':'未配置固定报告');}
async function readback(){if(!credential||polling)return;clearTimeout(timer);timer=null;const own=epoch;polling=true;try{const state=await api('/api/portal/state');if(own!==epoch)return;if(state.mutation_status==='UNKNOWN'){unknown=true;show('receipt',state.receipts);show('status','UNKNOWN · 上次请求仍被隔离，只读核对，不重发。');}show('binding',state.binding.status+' · 固定方案核验：'+state.spec.status+' · spec SHA '+state.spec.sha256);$('create').hidden=state.binding.status!=='NEW';if(state.binding.chat_id){const v=await api('/api/portal/chat');if(own!==epoch)return;renderChat(v);if(v.mission_id){const snap=await api('/api/portal/snapshot');if(own!==epoch)return;renderCapture(snap);const inbox=await api('/api/portal/messages?cursor=0&application_cursor=0');if(own!==epoch)return;show('inbox',inbox);const placements=await api('/api/portal/placements'),nodes=await api('/api/portal/nodes');if(own!==epoch)return;renderPlacements(placements,nodes);}}if(!unknown)show('status','已只读刷新。捕获与回执以控制器事实为准。');}catch(e){if(own===epoch)show('status','STALE · '+e.message+'；保留上次捕获但它不是最新状态。');}finally{if(own===epoch){polling=false;timer=setTimeout(readback,5000);buttons();}}}
function renderPlacements(v,nodes){$('placements').replaceChildren();for(const t of v.tasks||v.placements||[]){const row=element('article');row.append(element('p',t.task_id+' · '+JSON.stringify(t.placement)));const select=element('select');select.setAttribute('aria-label','任务 '+t.task_id+' 的机器');select.append(new Option('本机 / 保留当前安排',''));for(const n of nodes.nodes||[])if(n.status==='ACTIVE')select.append(new Option(n.name,n.node_id));const save=element('button','选择这台机器');save.disabled=busy||unknown||chat?.placement_preparation?.status!=='ACK'||!!chat?.placement_start;save.onclick=()=>{if(select.value)mutate('/api/portal/placement',{task_id:t.task_id,node_id:select.value});};row.append(select,save);$('placements').append(row);}}
async function mutate(path,body){if(busy||unknown)return;const own=epoch;const request_id=crypto.randomUUID();busy=true;buttons();show('receipt','发送中 · '+request_id);try{const v=await api(path,{...body,request_id});if(own!==epoch)return;show('receipt','收到回执 · '+request_id+'（不等于执行完成）');if(v.id)renderChat(v);await readback();}catch(e){if(own!==epoch)return;unknown=!e.status||e.status>=500;show('receipt',(unknown?'UNKNOWN · 保持只读核对，不重发':'REJECTED')+' · '+request_id+' · '+e.message);if(unknown)show('status','请求结果未知。只读刷新核对；由本机控制器处理不确定状态。');}finally{if(own===epoch){busy=false;buttons();}}}
$('login').onsubmit=async e=>{e.preventDefault();if(busy)return;let password=$('password').value;clearPrivate();busy=true;const own=epoch;try{const pending=api('/api/portal/login',{password},'');password='';const v=await pending;if(own!==epoch)return;if(v.schema!=='sisyfus.share.session.v1'||typeof v.token!=='string'||!/^[A-Za-z0-9_-]{43}$/.test(v.token)||v.expires_in!==28800)throw new RequestError('INVALID_SESSION');credential=v.token;$('login').hidden=true;$('private').hidden=false;$('logout').hidden=false;await readback();}catch(e){if(own===epoch)show('status','登录失败 · '+e.message);}finally{if(own===epoch)busy=false;buttons();}};
$('logout').onclick=async()=>{const session=credential;clearPrivate();show('status','私有内容已清除。');if(!session)return;if(revoking>=16){show('revoke','服务器会话撤销未确认；不自动重试。');return;}revoking++;const c=new AbortController(),timeout=setTimeout(()=>c.abort(),14000);try{const r=await fetch('/api/portal/logout',{method:'POST',headers:{Authorization:'Bearer '+session},signal:c.signal,credentials:'omit',cache:'no-store',redirect:'error'});if(!r.ok||(await r.json()).status!=='LOGGED_OUT')throw new Error();show('revoke','服务器已确认会话撤销。');}catch{show('revoke','服务器会话撤销未确认；不自动重试。');}finally{clearTimeout(timeout);revoking--;}};
$('create').onclick=()=>mutate('/api/portal/chat',{});$('refresh').onclick=()=>{clearTimeout(timer);readback();};$('chat-form').onsubmit=e=>{e.preventDefault();if(!e.isComposing)mutate('/api/portal/chat/message',{message:$('chat-text').value});};$('inbox-form').onsubmit=e=>{e.preventDefault();mutate('/api/portal/message',{message:$('inbox-text').value});};$('prepare').onclick=()=>{if(!$('planning').checked){show('receipt','请单独勾选规划许可。');return;}mutate('/api/portal/chat/prepare-placement',{allow_planning:true,approval_hash:chat.approval_hash});};$('start').onclick=()=>{if(!$('execution').checked){show('receipt','请单独勾选 worker 执行许可。');return;}mutate('/api/portal/chat/start',{allow_local_workers:true,approval_hash:chat.placement_preparation.approval_hash});};
$('report-open').onclick=async()=>{const own=epoch,c=new AbortController(),timeout=setTimeout(()=>c.abort(),14000);requests.add(c);try{const r=await fetch('/api/portal/report',{headers:{Authorization:'Bearer '+credential},signal:c.signal,credentials:'omit',redirect:'error',cache:'no-store'});if(!r.ok){if([401,403,410].includes(r.status)){clearPrivate();show('status','报告读取会话失效；私有内容已清除，请重新登录。');}throw new RequestError('REPORT_REJECTED',r.status);}const raw=await r.arrayBuffer();if(own!==epoch)return;const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(v=>v.toString(16).padStart(2,'0')).join('');if(own!==epoch)return;if(hash!==capture?.report?.sha256)throw new RequestError('REPORT_VERSION_CHANGED');if(reportURL)URL.revokeObjectURL(reportURL);reportURL=URL.createObjectURL(new Blob([raw],{type:'text/html'}));$('report').src=reportURL;$('report').hidden=false;}catch(e){if(own===epoch)show('report-version','固定报告读取失败 · '+e.message);}finally{clearTimeout(timeout);requests.delete(c);}};
</script></main></body></html>'''
